        ev=["Jats", "farming community", "Ganga–Yamuna Doab", "heavy taxes and exploitation", "economic hardships", "Aurangzeb's religious policies", "growing resentment"],
        checks=[("jt_causes", "States that the Jats, a farming community of the Ganga-Yamuna Doab, were burdened with heavy taxes and exploitation by the Mughals, which together with Aurangzeb's religious policies created growing resentment.", True)],
